59: /** Real HTTP SDK fixture used as an external server by the isolated application. */
60: export async function startProjectionMcp(canary: string) {
61:   const calls: Call[] = []
62:   const server = toolServer(canary, calls)
63:   const transport = new StreamableHTTPServerTransport({ sessionIdGenerator: randomUUID })
64:   await server.connect(transport)
65:   let authorized = 0
66:   const http = createServer((request, response) => {
67:     if (request.headers.authorization !== `Bearer ${canary}`) {
68:       response.writeHead(403).end()
69:       return
70:     }
71:     authorized += 1
72:     void transport.handleRequest(request, response).catch(() => {
73:       if (!response.headersSent) response.writeHead(500)
74:       response.end()
75:     })
76:   })
77:   await new Promise<void>((resolve) => http.listen(0, '127.0.0.1', resolve))
78:   const address = http.address()
79:   assert(address && typeof address !== 'string')
80:   return {
81:     url: `http://127.0.0.1:${address.port}/mcp`, calls,
82:     authenticatedRequests: () => authorized,
83:     async close() {
84:       await server.close()
85:       http.closeAllConnections()
86:       await new Promise<void>((resolve) => http.close(() => resolve()))
87:     }
88:   }
89: }
