8: /// Maximum MCP descriptors advertised in one model step, excluding controls.
9: pub const MCP_EAGER_TOOL_LIMIT: usize = 32;
10: /// Maximum deferred descriptors selected by one search call.
11: pub const MCP_SEARCH_RESULT_LIMIT: usize = 8;
12: /// Bounded model input for local descriptor matching, in Unicode characters.
13: pub const MCP_SEARCH_QUERY_LIMIT: usize = 512;
