95:             .selected
96:             .iter()
97:             .map(|tool| tool.provider_name.clone())
98:             .collect::<BTreeSet<_>>();
99:         for (name, tool) in authorized {
100:             if selected.len() >= MCP_EAGER_TOOL_LIMIT {
101:                 break;
102:             }
103:             if tool.source == ToolSource::Mcp
104:                 && matches!(tool.exposure, Exposure::Eager | Exposure::ModelOnly)
105:             {
106:                 selected.insert(name.clone());
107:             }
108:         }
109:         let mut visible = BTreeMap::new();
110:         let mut deferred = BTreeMap::new();
111:         for (name, tool) in authorized {
112:             if tool.exposure == Exposure::Hidden {
113:                 continue;
114:             }
115:             if tool.source == ToolSource::Mcp {
116:                 if selected.contains(name) {
117:                     visible.insert(name.clone(), Arc::clone(tool));
118:                 } else {
119:                     deferred.insert(name.clone(), Arc::clone(tool));
120:                 }
121:             } else if matches!(tool.exposure, Exposure::Eager | Exposure::ModelOnly) {
122:                 visible.insert(name.clone(), Arc::clone(tool));
123:             }
124:         }
125:         let snapshot = McpExposureSnapshot {
126:             visible,
127:             deferred: deferred.keys().cloned().collect(),
128:         };
129:         state.deferred = deferred;
130:         snapshot
131:     }
