133:     /// Select matching deferred tools for the next projection, without I/O.
134:     /// All query terms must match the name, ID, server or description. Exact
135:     /// provider-name matches rank first, then names, then descriptive matches.
136:     ///
137:     /// # Errors
138:     /// Rejects blank or oversized model input; no query is echoed in the error.
139:     pub fn search(&self, query: &str) -> anyhow::Result<Vec<Arc<ToolDescriptor>>> {
140:         anyhow::ensure!(
141:             !query.trim().is_empty() && query.chars().count() <= MCP_SEARCH_QUERY_LIMIT,
142:             "query must contain 1 to {MCP_SEARCH_QUERY_LIMIT} characters and not be blank"
143:         );
144:         let query = query.trim().to_lowercase();
145:         let terms = query.split_whitespace().collect::<Vec<_>>();
146:         let mut state = self
147:             .0
148:             .write()
149:             .unwrap_or_else(std::sync::PoisonError::into_inner);
150:         let mut matches = state
151:             .deferred
152:             .values()
153:             .filter_map(|tool| {
154:                 let name = tool.provider_name.to_lowercase();
155:                 let identity = format!(
156:                     "{} {} {}",
157:                     name,
158:                     tool.id,
159:                     tool.server.as_deref().unwrap_or_default()
160:                 )
161:                 .to_lowercase();
162:                 let searchable = format!("{} {}", identity, tool.description.to_lowercase());
163:                 if !terms.iter().all(|term| searchable.contains(term)) {
164:                     return None;
165:                 }
166:                 let rank = if name == query {
167:                     0
168:                 } else if terms.iter().all(|term| identity.contains(term)) {
169:                     1
170:                 } else {
171:                     2
172:                 };
173:                 Some((rank, Arc::clone(tool)))
174:             })
175:             .collect::<Vec<_>>();
176:         matches.sort_by(|(left_rank, left), (right_rank, right)| {
177:             left_rank
178:                 .cmp(right_rank)
179:                 .then_with(|| left.provider_name.cmp(&right.provider_name))
180:         });
181:         let matches = matches
182:             .into_iter()
183:             .take(MCP_SEARCH_RESULT_LIMIT)
184:             .map(|(_, tool)| tool)
185:             .collect::<Vec<_>>();
186:         for tool in matches.iter().rev() {
187:             state
188:                 .selected
189:                 .retain(|prior| prior.provider_name != tool.provider_name);
190:             state.selected.insert(0, Arc::clone(tool));
191:         }
192:         state.selected.truncate(MCP_EAGER_TOOL_LIMIT);

